-- Finance owns receivable projection; tender facts remain immutable evidence.
CREATE TABLE receivable_balance(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,sale_id uuid NOT NULL,outstanding_xaf bigint NOT NULL CHECK(outstanding_xaf>=0),version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,sale_id),FOREIGN KEY(tenant_id,company_id,sale_id) REFERENCES sale(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE cash_session(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,till_code varchar(80) NOT NULL,business_date date NOT NULL,status text NOT NULL CHECK(status IN('OPEN','CLOSED')),opening_xaf bigint NOT NULL CHECK(opening_xaf>=0),counted_xaf bigint CHECK(counted_xaf>=0),actor_id uuid NOT NULL,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
ALTER TABLE cash_session ADD COLUMN activity_sequence bigint NOT NULL DEFAULT 0;
CREATE UNIQUE INDEX cash_one_open_till ON cash_session(tenant_id,company_id,branch_id,till_code) WHERE status='OPEN';
CREATE TABLE deposit_balance(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,customer_id uuid NOT NULL,original_xaf bigint NOT NULL CHECK(original_xaf>0),allocated_xaf bigint NOT NULL DEFAULT 0 CHECK(allocated_xaf>=0),refunded_xaf bigint NOT NULL DEFAULT 0 CHECK(refunded_xaf>=0),version bigint NOT NULL DEFAULT 0,CHECK(allocated_xaf::numeric+refunded_xaf::numeric<=original_xaf),PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,customer_id) REFERENCES customer(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE tender_fact(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,operation_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('RECEIPT','DEPOSIT','ALLOCATION','REFUND','VARIANCE','EXPENSE')),customer_id uuid,sale_id uuid,deposit_id uuid,cash_session_id uuid,business_date date NOT NULL,amount_xaf bigint NOT NULL CHECK(amount_xaf>0),cash_delta_xaf bigint NOT NULL,journal_id uuid NOT NULL,reason text NOT NULL CHECK(length(trim(reason))>=3),actor_id uuid NOT NULL,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,sale_id) REFERENCES sale(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,customer_id) REFERENCES customer(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,deposit_id) REFERENCES deposit_balance(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,cash_session_id) REFERENCES cash_session(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,journal_id) REFERENCES journal_entry(tenant_id,company_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['receivable_balance','cash_session','deposit_balance','tender_fact'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch()) WITH CHECK(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())',t);END LOOP;END $$;
GRANT SELECT,INSERT,UPDATE ON receivable_balance,cash_session,deposit_balance TO quincai_app;
GRANT SELECT,INSERT ON tender_fact TO quincai_app;
CREATE TRIGGER tender_immutable BEFORE UPDATE OR DELETE ON tender_fact FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation();
CREATE FUNCTION protect_closed_cash() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='CLOSED' THEN RAISE EXCEPTION 'Closed cash session immutable';END IF;IF NEW.opening_xaf<>OLD.opening_xaf OR NEW.business_date<>OLD.business_date OR NEW.till_code<>OLD.till_code THEN RAISE EXCEPTION 'Cash session opening cannot change';END IF;RETURN NEW;END $$;
CREATE TRIGGER closed_cash_immutable BEFORE UPDATE ON cash_session FOR EACH ROW EXECUTE FUNCTION protect_closed_cash();
CREATE FUNCTION check_tender_cash() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE shift cash_session; BEGIN IF NEW.cash_session_id IS NOT NULL THEN SELECT * INTO shift FROM cash_session WHERE tenant_id=NEW.tenant_id AND company_id=NEW.company_id AND id=NEW.cash_session_id FOR UPDATE;IF shift.id IS NULL OR shift.status<>'OPEN' OR shift.business_date<>NEW.business_date OR shift.branch_id<>NEW.branch_id THEN RAISE EXCEPTION 'Matching open cash session required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER tender_cash_open BEFORE INSERT ON tender_fact FOR EACH ROW EXECUTE FUNCTION check_tender_cash();
CREATE TABLE provider_intent(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,operation_id uuid NOT NULL,sale_id uuid NOT NULL,actor_id uuid NOT NULL,business_date date NOT NULL,amount_xaf bigint NOT NULL CHECK(amount_xaf>0),currency text NOT NULL,environment text NOT NULL CHECK(environment IN('sandbox','mtncameroon')),phone text NOT NULL,status text NOT NULL CHECK(status IN('QUEUED','UNKNOWN','PENDING','FAILED','SANDBOX_VERIFIED','PROVIDER_VERIFIED_REVIEW','CONFIRMED')),reason text NOT NULL,financial_transaction_id text,journal_id uuid,query_due boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id,sale_id) REFERENCES sale(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,journal_id) REFERENCES journal_entry(tenant_id,company_id,id),CHECK((environment='sandbox' AND currency='EUR' AND journal_id IS NULL AND status<>'CONFIRMED') OR (environment='mtncameroon' AND currency='XAF')),CHECK(status<>'CONFIRMED' OR (financial_transaction_id IS NOT NULL AND journal_id IS NOT NULL)));
CREATE UNIQUE INDEX provider_financial_once ON provider_intent(environment,financial_transaction_id) WHERE financial_transaction_id IS NOT NULL;
ALTER TABLE provider_intent ENABLE ROW LEVEL SECURITY;ALTER TABLE provider_intent FORCE ROW LEVEL SECURITY;
CREATE POLICY scope_isolation ON provider_intent USING(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch()) WITH CHECK(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch());
GRANT SELECT,INSERT,UPDATE ON provider_intent TO quincai_app;
CREATE FUNCTION protect_provider_intent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.sale_id<>OLD.sale_id OR NEW.amount_xaf<>OLD.amount_xaf OR NEW.currency<>OLD.currency OR NEW.phone<>OLD.phone OR NEW.environment<>OLD.environment OR NEW.operation_id<>OLD.operation_id THEN RAISE EXCEPTION 'Provider request identity immutable';END IF;IF OLD.financial_transaction_id IS NOT NULL AND NEW.financial_transaction_id IS DISTINCT FROM OLD.financial_transaction_id THEN RAISE EXCEPTION 'Verified provider reference immutable';END IF;IF OLD.status='CONFIRMED' AND (NEW.status<>OLD.status OR NEW.journal_id IS DISTINCT FROM OLD.journal_id) THEN RAISE EXCEPTION 'Confirmed provider accounting immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER provider_identity_immutable BEFORE UPDATE ON provider_intent FOR EACH ROW EXECUTE FUNCTION protect_provider_intent();
ALTER TABLE financial_period ADD COLUMN version bigint NOT NULL DEFAULT 0;
CREATE TABLE period_change_request(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,period_id uuid NOT NULL,action text NOT NULL CHECK(action IN('CLOSE','REOPEN')),status text NOT NULL CHECK(status IN('REQUESTED','APPROVED','REJECTED')),requested_by uuid NOT NULL,decided_by uuid,period_version bigint NOT NULL,version bigint NOT NULL DEFAULT 0,reason text NOT NULL CHECK(length(trim(reason))>=3),PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,period_id) REFERENCES financial_period(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id),CHECK(status='REQUESTED' OR (decided_by IS NOT NULL AND requested_by<>decided_by)));
CREATE UNIQUE INDEX one_pending_period_change ON period_change_request(tenant_id,company_id,period_id)WHERE status='REQUESTED';
CREATE TABLE operating_expense(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,created_by uuid NOT NULL,submitted_by uuid,approved_by uuid,business_date date NOT NULL,category text NOT NULL,payee text NOT NULL,amount_xaf bigint NOT NULL CHECK(amount_xaf>0),reason text NOT NULL,status text NOT NULL CHECK(status IN('DRAFT','IN_REVIEW','APPROVED','REJECTED','POSTED','CANCELLED')),paid_fact_id uuid,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id) REFERENCES branch(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,paid_fact_id) REFERENCES tender_fact(tenant_id,company_id,id),CHECK(status NOT IN('APPROVED','POSTED') OR (approved_by IS NOT NULL AND submitted_by IS NOT NULL AND approved_by<>submitted_by)),CHECK((status='POSTED')=(paid_fact_id IS NOT NULL)));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['period_change_request','operating_expense'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())WITH CHECK(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())',t);END LOOP;END $$;
GRANT SELECT,INSERT,UPDATE ON period_change_request,operating_expense TO quincai_app;
GRANT INSERT ON financial_period TO quincai_app;
GRANT UPDATE(status,version)ON financial_period TO quincai_app;
CREATE FUNCTION protect_expense_posted()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.status IN('POSTED','CANCELLED')THEN RAISE EXCEPTION 'Final expense immutable';END IF;IF NEW.amount_xaf<>OLD.amount_xaf OR NEW.business_date<>OLD.business_date OR NEW.category<>OLD.category OR NEW.payee<>OLD.payee THEN RAISE EXCEPTION 'Expense revision requires a new draft';END IF;RETURN NEW;END$$;
CREATE TRIGGER expense_immutable BEFORE UPDATE ON operating_expense FOR EACH ROW EXECUTE FUNCTION protect_expense_posted();
CREATE FUNCTION protect_period_decision()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.status<>'REQUESTED' THEN RAISE EXCEPTION 'Period decision immutable';END IF;IF NEW.period_id<>OLD.period_id OR NEW.requested_by<>OLD.requested_by OR NEW.action<>OLD.action OR NEW.reason<>OLD.reason OR NEW.period_version<>OLD.period_version THEN RAISE EXCEPTION 'Period approval request immutable';END IF;RETURN NEW;END$$;
CREATE TRIGGER period_decision_immutable BEFORE UPDATE ON period_change_request FOR EACH ROW EXECUTE FUNCTION protect_period_decision();
-- The application may change status only in the same transaction as an independently approved request.
ALTER TABLE period_change_request ADD COLUMN decision_transaction_id xid8, ADD COLUMN decision_reason text;
CREATE FUNCTION stamp_period_decision()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NEW.status<>'REQUESTED' THEN
  IF NEW.decision_reason IS NULL OR length(trim(NEW.decision_reason))<3 THEN RAISE EXCEPTION 'Decision reason required';END IF;
  IF NEW.decided_by IS DISTINCT FROM app_actor() OR NEW.requested_by=app_actor() THEN RAISE EXCEPTION 'Independent current actor required' USING ERRCODE='42501';END IF;
  NEW.decision_transaction_id=pg_current_xact_id();
 END IF;RETURN NEW;END$$;
CREATE TRIGGER stamp_period_decision BEFORE UPDATE ON period_change_request FOR EACH ROW EXECUTE FUNCTION stamp_period_decision();
CREATE FUNCTION guard_period_status()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NEW.status IS DISTINCT FROM OLD.status AND current_setting('is_superuser')<>'on' THEN
  IF NOT EXISTS(SELECT FROM period_change_request r WHERE r.tenant_id=OLD.tenant_id AND r.company_id=OLD.company_id AND r.period_id=OLD.id AND r.period_version=OLD.version AND r.status='APPROVED' AND r.decided_by=app_actor() AND r.decision_transaction_id=pg_current_xact_id() AND r.action=CASE WHEN NEW.status='Closed' THEN 'CLOSE' ELSE 'REOPEN' END)THEN RAISE EXCEPTION 'Approved current transaction period request required' USING ERRCODE='42501';END IF;
 END IF;RETURN NEW;END$$;
CREATE TRIGGER guard_period_status BEFORE UPDATE ON financial_period FOR EACH ROW EXECUTE FUNCTION guard_period_status();
